def get_fix_options(policy_file: Dict[str, Any], auto_remediation_limit: int
    ) ->int:
    if policy_file:
        fix_config = policy_file.get('fix', {})
        auto_remediation_limit_config = fix_config.get('auto-security-updates-limit', None)
        if auto_remediation_limit_config:
            return auto_remediation_limit_config

    return auto_remediation_limit
